inline i32 bsNextInt(u64 *rand, const i32 n) {
  bool r = (n - 1 & n);
  bool r2 = n - 1;
  u64 m = r - 1;
  u64 m2 = !r2 - 1;
  *rand = (*rand * (1|(25214903917&m2)) + (11&m2)) & MASK_48;
  u64 x = ((m & n) | r) * (*rand >> 17);
  return ((x&m2) >> (31&m)) % (n + (4294960000&m));
}
inline i32 bsBoundedNextInt(u64 *rand, const i32 min, const i32 max) {
  return min + bsNextInt(rand, max - min + 1);
}

